import {expect} from '@playwright/test';
export async function exerciseFacets(page,{lang='zh',rows,screenshot,reopen,saved}){
  const text=(zh,en)=>lang==='en'?en:zh,pop=page.locator('.facet-popover'),cards=page.locator('.photo-caption>span'),wanted=ids=>ids.map(id=>rows.find(p=>p.id===id).file_name).sort(),seen=async ids=>expect.poll(async()=>(await cards.allTextContents()).sort()).toEqual(wanted(ids));
  async function open(field){await page.locator('[data-facet="'+field+'"]').click();await expect(pop.getByRole('status')).toHaveText(text('当前范围：','In scope: ')+5);}
  const close=()=>pop.getByRole('button',{name:text('关闭筛选','Close filter'),exact:true}).click(),clear=()=>pop.getByRole('button',{name:text('清除此项','Clear this filter'),exact:true}).click();
  const option=name=>pop.getByRole('checkbox',{name:new RegExp('^'+name+'(?:\\s|$)')});
  async function choose(fields){await page.getByRole('button',{name:text('自定义筛选栏','Customize filters'),exact:true}).click();const dialog=page.getByRole('dialog',{name:text('自定义筛选栏','Customize filters'),exact:true});for(const [label,on] of fields)await dialog.getByRole('checkbox',{name:label,exact:true}).setChecked(on);await dialog.getByRole('button',{name:text('完成','Done'),exact:true}).click();}
  await seen(['a','b','c','d','e']);await page.getByRole('button',{name:text('筛选','Filter'),exact:true}).click();await open('camera_model');await option('SONY').check();await seen(['a','c','e']);await option('Canon').check();await seen(['a','b','c','e']);await pop.getByRole('button',{name:text('排除','Exclude'),exact:true}).click();await seen(['d']);await option('Canon').uncheck();await seen(['b','d']);await close();
  await choose([[text('相机','Camera'),false],[text('ISO','ISO'),true],[text('拍摄时间','Date taken'),true],[text('画幅','Orientation'),true]]);await expect(page.locator('[data-facet=camera_model]')).toBeVisible();await open('camera_model');await clear();await seen(['a','b','c','d','e']);await expect(page.locator('[data-facet=camera_model]')).toHaveCount(0);await expect.poll(async()=>(await saved())?.hidden?.includes('camera_model')??false).toBe(true);
  await reopen();await page.getByRole('button',{name:text('筛选','Filter'),exact:true}).click();await expect(page.locator('[data-facet=camera_model]')).toHaveCount(0);await open('tag');await option('旅行').check();await option('人像').check();await pop.getByRole('combobox',{name:text('标签匹配方式','Tag match mode'),exact:true}).selectOption('all');await seen(['a']);await close();
  await page.locator('[data-facet=iso]').click();await expect(pop.getByRole('status')).toContainText(text('当前范围：1','In scope: 1'));await pop.getByRole('button',{name:text('范围','Range'),exact:true}).click();await pop.getByRole('spinbutton',{name:text('起始值','From'),exact:true}).fill('800');await pop.getByRole('spinbutton',{name:text('结束值','Through'),exact:true}).fill('800');await pop.getByRole('button',{name:text('应用条件','Apply'),exact:true}).click();await seen([]);await close();
  await page.locator('[data-facet=tag]').click();await expect(pop.getByRole('status')).toContainText(text('当前范围：1','In scope: 1'));await expect(pop.locator('.facet-options label').filter({hasText:'旅行'}).locator('small')).toHaveText('0');await expect(option('旅行')).toBeChecked();await clear();await seen(['c']);await open('iso');await clear();
  await open('date_taken');await pop.getByLabel(text('起始值','From'),{exact:true}).fill('2026-01-01');await pop.getByLabel(text('结束值','Through'),{exact:true}).fill('2026-01-01');await pop.getByRole('button',{name:text('应用条件','Apply'),exact:true}).click();await seen(['a','b','e']);await option(text('未设置','Not set')).check();await seen(['a','b','d','e']);await pop.getByRole('button',{name:text('排除','Exclude'),exact:true}).click();await seen(['c']);await clear();
  await open('orientation');await option(text('竖幅','Portrait')).check();await option(text('方形','Square')).check();await seen(['b','c']);if(screenshot)await page.screenshot({path:screenshot,fullPage:true});expect(await pop.evaluate(el=>el.scrollWidth<=el.clientWidth+1)).toBe(true);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);const aligned=await pop.locator('.facet-options label').first().evaluate(el=>{const rects=[...el.children].map(n=>n.getBoundingClientRect());return Math.max(...rects.map(r=>r.top+r.height/2))-Math.min(...rects.map(r=>r.top+r.height/2))<4;});expect(aligned).toBe(true);await close();
}
